def life_generations(grid: list[list[int]], gens: int) -> int:
    h: int = len(grid)
    w: int = len(grid[0])
    cells: list[list[int]] = []
    for y in range(h):
        row: list[int] = []
        for x in range(w):
            row.append(grid[y][x])
        cells.append(row)
    for g in range(gens):
        nxt: list[list[int]] = []
        for y in range(h):
            nrow: list[int] = []
            for x in range(w):
                total: int = 0
                for dy in range(-1, 2):
                    for dx in range(-1, 2):
                        if dy != 0 or dx != 0:
                            total += cells[(y + dy) % h][(x + dx) % w]
                alive: int = 0
                if total == 3 or (cells[y][x] == 1 and total == 2):
                    alive = 1
                nrow.append(alive)
            nxt.append(nrow)
        cells = nxt
    count: int = 0
    for y in range(h):
        for x in range(w):
            count += cells[y][x]
    return count
